import 'dart:async';
import 'dart:convert';
import 'dart:io';
import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;
import 'package:watcher/watcher.dart';
import 'package:permission_handler/permission_handler.dart';
import 'package:flutter_markdown/flutter_markdown.dart';
import 'package:shared_preferences/shared_preferences.dart';

void main() {
  runApp(const SayCheeseAgentApp());
}

class EjercicioResuelto {
  final String id;
  final String? rutaImagen;
  final String? miniaturaBase64;
  final DateTime fecha;
  final String autor;
  final String modeloUsado;
  String? solucion;
  bool procesando;

  EjercicioResuelto({
    required this.id,
    this.rutaImagen,
    this.miniaturaBase64,
    required this.fecha,
    this.autor = 'Local',
    this.modeloUsado = 'gemini-3.1-pro-preview',
    this.solucion,
    this.procesando = true,
  });

  Map<String, dynamic> toJson() => {
        'id': id,
        'rutaImagen': rutaImagen,
        'miniaturaBase64': miniaturaBase64,
        'fecha': fecha.toIso8601String(),
        'autor': autor,
        'modeloUsado': modeloUsado,
        'solucion': solucion,
        'procesando': procesando,
      };

  factory EjercicioResuelto.fromJson(Map<String, dynamic> json) =>
      EjercicioResuelto(
        id: json['id'] ?? DateTime.now().millisecondsSinceEpoch.toString(),
        rutaImagen: json['rutaImagen'],
        miniaturaBase64: json['miniaturaBase64'],
        fecha: DateTime.tryParse(json['fecha'] ?? '') ?? DateTime.now(),
        autor: json['autor'] ?? 'Compañero',
        modeloUsado: json['modeloUsado'] ?? 'gemini-3.1-pro-preview',
        solucion: json['solucion'],
        procesando: json['procesando'] ?? false,
      );
}

class SayCheeseAgentApp extends StatelessWidget {
  const SayCheeseAgentApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'SayCheese Agent 3.0',
      debugShowCheckedModeBanner: false,
      theme: ThemeData.dark(useMaterial3: true).copyWith(
        colorScheme: ColorScheme.fromSeed(
          seedColor: Colors.deepPurpleAccent,
          brightness: Brightness.dark,
        ),
      ),
      home: const HomeScreen(),
    );
  }
}

class HomeScreen extends StatefulWidget {
  const HomeScreen({super.key});

  @override
  State<HomeScreen> createState() => _HomeScreenState();
}

class _HomeScreenState extends State<HomeScreen> {
  int _pestanaActual = 0;
  bool _agenteActivo = false;
  StreamSubscription<WatchEvent>? _watcherSub;
  Timer? _syncTimer;
  final List<EjercicioResuelto> _historial = [];

  final String _rutaCarpeta = '/storage/emulated/0/Pictures/SayCheese';

  String _apiKey = const String.fromEnvironment(
    'GEMINI_API_KEY',
    defaultValue: '',
  );

  // Selector de modelos actualizado (con gemini-3.1-pro-preview por defecto)
  String _modeloSeleccionado = 'gemini-3.1-pro-preview';
  final List<String> _modelosDisponibles = [
    'gemini-3.1-pro-preview',
    'gemini-3-flash-preview',
    'gemini-2.5-flash',
    'gemini-2.5-pro',
  ];

  // Sala compartida entre 2 personas
  String _codigoSala = '';
  String _aliasUsuario = 'Usuario 1';
  bool _sincronizando = false;

  @override
  void initState() {
    super.initState();
    _cargarDatosLocales();
    _iniciarAgente();
    // Sincronizacion automatica cada 10 segundos si hay una sala conectada
    _syncTimer = Timer.periodic(const Duration(seconds: 10), (_) {
      if (_codigoSala.isNotEmpty) {
        _sincronizarSalaCompartida(silencioso: true);
      }
    });
  }

  Future<void> _cargarDatosLocales() async {
    final prefs = await SharedPreferences.getInstance();
    final savedKey = prefs.getString('gemini_api_key');
    if (savedKey != null && savedKey.isNotEmpty) {
      setState(() => _apiKey = savedKey);
    }

    final savedModel = prefs.getString('gemini_model');
    if (savedModel != null && savedModel.isNotEmpty) {
      if (!_modelosDisponibles.contains(savedModel)) {
        _modelosDisponibles.insert(0, savedModel);
      }
      setState(() => _modeloSeleccionado = savedModel);
    }

    final savedSala = prefs.getString('sala_compartida') ?? '';
    final savedAlias = prefs.getString('alias_usuario') ?? 'Usuario 1';
    setState(() {
      _codigoSala = savedSala;
      _aliasUsuario = savedAlias;
    });

    final historialJson = prefs.getStringList('historial_ejercicios_v3') ?? [];
    setState(() {
      _historial.clear();
      _historial.addAll(
        historialJson.map((e) => EjercicioResuelto.fromJson(jsonDecode(e))),
      );
    });

    if (_codigoSala.isNotEmpty) {
      _sincronizarSalaCompartida(silencioso: true);
    }
  }

  Future<void> _guardarHistorialLocal() async {
    final prefs = await SharedPreferences.getInstance();
    final listaJson = _historial.map((e) => jsonEncode(e.toJson())).toList();
    await prefs.setStringList('historial_ejercicios_v3', listaJson);
  }

  // URL de sincronizacion en la nube usando sala unica por codigo
  Uri _obtenerUrlSala(String sala) {
    final hashSala = base64Url.encode(utf8.encode('saycheese_room_$sala')).replaceAll('=', '');
    return Uri.parse('https://kvdb.io/A6Xy9kLmN2pQrStUvWxYz/$hashSala');
  }

  Future<void> _subirASalaCompartida() async {
    if (_codigoSala.trim().isEmpty) return;
    try {
      final resueltos = _historial.where((e) => !e.procesando && e.solucion != null).take(20).map((e) => {
        'id': e.id,
        'fecha': e.fecha.toIso8601String(),
        'autor': e.autor,
        'modeloUsado': e.modeloUsado,
        'solucion': e.solucion,
        'procesando': false,
      }).toList();

      await http.post(
        _obtenerUrlSala(_codigoSala.trim()),
        headers: {'Content-Type': 'application/json'},
        body: jsonEncode(resueltos),
      );
    } catch (_) {}
  }

  Future<void> _sincronizarSalaCompartida({bool silencioso = false}) async {
    if (_codigoSala.trim().isEmpty) return;
    if (!silencioso) setState(() => _sincronizando = true);

    try {
      final res = await http.get(_obtenerUrlSala(_codigoSala.trim()));
      if (res.statusCode == 200 && res.body.isNotEmpty) {
        final Listremota = jsonDecode(res.body) as List;
        bool huboCambios = false;

        for (final raw in Listremota) {
          final itemRemoto = EjercicioResuelto.fromJson(raw as Map<String, dynamic>);
          final existeIdx = _historial.indexWhere((local) => local.id == itemRemoto.id);
          if (existeIdx == -1) {
            _historial.add(itemRemoto);
            huboCambios = true;
          } else if (_historial[existeIdx].solucion != itemRemoto.solucion && itemRemoto.solucion != null) {
            _historial[existeIdx].solucion = itemRemoto.solucion;
            _historial[existeIdx].procesando = false;
            huboCambios = true;
          }
        }

        if (huboCambios) {
          _historial.sort((a, b) => b.fecha.compareTo(a.fecha));
          setState(() {});
          await _guardarHistorialLocal();
        }
      }
      await _subirASalaCompartida();
    } catch (_) {
    } finally {
      if (!silencioso && mounted) setState(() => _sincronizando = false);
    }
  }

  Future<void> _iniciarAgente() async {
    await [
      Permission.photos,
      Permission.storage,
      Permission.manageExternalStorage,
    ].request();

    final dir = Directory(_rutaCarpeta);
    if (!await dir.exists()) {
      try {
        await dir.create(recursive: true);
      } catch (_) {}
    }

    final watcher = DirectoryWatcher(_rutaCarpeta);
    _watcherSub = watcher.events.listen((event) {
      final pathLower = event.path.toLowerCase();
      if (event.type == ChangeType.ADD &&
          (pathLower.endsWith('.jpg') ||
              pathLower.endsWith('.jpeg') ||
              pathLower.endsWith('.png'))) {
        _procesarNuevaFoto(File(event.path));
      }
    });

    setState(() => _agenteActivo = true);
  }

  Future<void> _procesarNuevaFoto(File archivoImagen) async {
    await Future.delayed(const Duration(seconds: 2));

    final nuevoItem = EjercicioResuelto(
      id: DateTime.now().millisecondsSinceEpoch.toString(),
      rutaImagen: archivoImagen.path,
      fecha: DateTime.now(),
      autor: _aliasUsuario,
      modeloUsado: _modeloSeleccionado,
    );

    setState(() {
      _historial.insert(0, nuevoItem);
    });

    await _intentarResolver(nuevoItem);
  }

  Future<void> _intentarResolver(EjercicioResuelto item) async {
    if (item.rutaImagen == null) return;
    setState(() {
      item.procesando = true;
      item.solucion = null;
    });

    try {
      final respuesta = await _llamarGemini(File(item.rutaImagen!), _modeloSeleccionado);
      setState(() {
        item.solucion = respuesta;
        item.procesando = false;
      });
      await _guardarHistorialLocal();
      await _subirASalaCompartida();
    } catch (e) {
      setState(() {
        item.solucion = 'Error al resolver la hoja: $e';
        item.procesando = false;
      });
      await _guardarHistorialLocal();
    }
  }

  Future<String> _llamarGemini(File imagen, String modelo) async {
    final keyLimpia = _apiKey.trim();
    if (keyLimpia.isEmpty) {
      throw Exception('Configura tu Gemini API Key (AIzaSy...) en el icono de engranaje superior.');
    }

    final bytes = await imagen.readAsBytes();
    final base64Image = base64Encode(bytes);

    // Lista de modelos con fallback automatico si Google desactiva alguno para cuentas nuevas
    final modelosIntento = <String>[
      modelo.trim(),
      if (modelo.trim() != 'gemini-3.1-pro-preview') 'gemini-3.1-pro-preview',
      if (modelo.trim() != 'gemini-2.5-flash') 'gemini-2.5-flash',
    ];

    String ultimoError = '';

    for (final modActual in modelosIntento) {
      final url = Uri.parse(
        'https://generativelanguage.googleapis.com/v1beta/models/$modActual:generateContent?key=$keyLimpia',
      );

      final Map<String, dynamic> payload = {
        "contents": [
          {
            "parts": [
              {
                "text":
                    "Resuelve todos los ejercicios de esta hoja paso a paso. Usa formato Markdown claro, enumera cada ejercicio y destaca el resultado final."
              },
              {
                "inline_data": {
                  "mime_type": "image/jpeg",
                  "data": base64Image,
                }
              }
            ]
          }
        ],
      };

      // Si el modelo soporta thinkingBudget (2.5), usamos presupuesto medio; en 3.x funciona directo
      if (modActual.contains('2.5')) {
        payload["generationConfig"] = {
          "thinkingConfig": {"thinkingBudget": 4096}
        };
      }

      http.Response? response;
      for (int i = 0; i < 3; i++) {
        try {
          response = await http.post(
            url,
            headers: {'Content-Type': 'application/json'},
            body: jsonEncode(payload),
          );
          break;
        } catch (e) {
          if (i == 2) rethrow;
          await Future.delayed(const Duration(seconds: 2));
        }
      }

      if (response!.statusCode == 200) {
        final data = jsonDecode(response.body);
        final parts = data['candidates'][0]['content']['parts'] as List;
        final textPart = parts.lastWhere(
          (p) => p.containsKey('text') && p['thought'] != true,
          orElse: () => parts.last,
        );
        return textPart['text'];
      } else if (response.statusCode == 404) {
        ultimoError = 'Modelo $modActual no disponible (404). Probando siguiente...';
        continue;
      } else {
        throw Exception('Codigo ${response.statusCode} ($modActual): ${response.body}');
      }
    }

    throw Exception(ultimoError);
  }

  void _mostrarDialogoConfiguracion() {
    final apiController = TextEditingController(text: _apiKey);
    final customModelController = TextEditingController(text: _modeloSeleccionado);
    String tempModel = _modeloSeleccionado;

    showDialog(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setDialogState) => AlertDialog(
          title: const Text('Ajustes de Gemini'),
          content: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                const Text(
                  '1. Clave de Google AI Studio (AIzaSy...):',
                  style: TextStyle(fontSize: 12, color: Colors.grey),
                ),
                const SizedBox(height: 6),
                TextField(
                  controller: apiController,
                  decoration: const InputDecoration(
                    hintText: 'AIzaSy...',
                    labelText: 'API Key',
                    border: OutlineInputBorder(),
                  ),
                ),
                const SizedBox(height: 16),
                const Text(
                  '2. Elegir Modelo de Gemini:',
                  style: TextStyle(fontSize: 12, color: Colors.grey),
                ),
                const SizedBox(height: 6),
                DropdownButtonFormField<String>(
                  value: _modelosDisponibles.contains(tempModel) ? tempModel : _modelosDisponibles.first,
                  isExpanded: true,
                  decoration: const InputDecoration(border: OutlineInputBorder()),
                  items: _modelosDisponibles
                      .map((m) => DropdownMenuItem(value: m, child: Text(m, style: const TextStyle(fontSize: 13))))
                      .toList(),
                  onChanged: (val) {
                    if (val != null) {
                      setDialogState(() {
                        tempModel = val;
                        customModelController.text = val;
                      });
                    }
                  },
                ),
                const SizedBox(height: 10),
                TextField(
                  controller: customModelController,
                  decoration: const InputDecoration(
                    labelText: 'O escribe el nombre exacto del modelo',
                    hintText: 'gemini-3.1-pro-preview',
                    border: OutlineInputBorder(),
                  ),
                ),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(ctx),
              child: const Text('Cancelar'),
            ),
            FilledButton(
              onPressed: () async {
                final modelFinal = customModelController.text.trim().isNotEmpty
                    ? customModelController.text.trim()
                    : tempModel;
                final prefs = await SharedPreferences.getInstance();
                await prefs.setString('gemini_api_key', apiController.text.trim());
                await prefs.setString('gemini_model', modelFinal);
                if (!_modelosDisponibles.contains(modelFinal)) {
                  _modelosDisponibles.insert(0, modelFinal);
                }
                setState(() {
                  _apiKey = apiController.text.trim();
                  _modeloSeleccionado = modelFinal;
                });
                if (mounted) Navigator.pop(ctx);
              },
              child: const Text('Guardar'),
            ),
          ],
        ),
      ),
    );
  }

  void _mostrarDialogoSalaCompartida() {
    final salaController = TextEditingController(text: _codigoSala);
    final aliasController = TextEditingController(text: _aliasUsuario);

    showDialog(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Conectar 2 Personas en Vivo'),
        content: SingleChildScrollView(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              const Text(
                'Si ambos escriben el mismo Codigo de Sala en su app, veran todas las hojas resueltas por cualquiera de los dos automaticamente.',
                style: TextStyle(fontSize: 12, color: Colors.grey),
              ),
              const SizedBox(height: 12),
              TextField(
                controller: aliasController,
                decoration: const InputDecoration(
                  labelText: 'Tu Nombre o Alias',
                  hintText: 'Ej: Leo',
                  border: OutlineInputBorder(),
                ),
              ),
              const SizedBox(height: 12),
              TextField(
                controller: salaController,
                decoration: const InputDecoration(
                  labelText: 'Codigo de Sala Compartida',
                  hintText: 'Ej: SALA-GEMINI-99',
                  border: OutlineInputBorder(),
                ),
              ),
            ],
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx),
            child: const Text('Cerrar'),
          ),
          FilledButton.icon(
            icon: const Icon(Icons.sync),
            label: const Text('Conectar y Sincronizar'),
            onPressed: () async {
              final prefs = await SharedPreferences.getInstance();
              await prefs.setString('sala_compartida', salaController.text.trim());
              await prefs.setString('alias_usuario', aliasController.text.trim().isEmpty ? 'Usuario' : aliasController.text.trim());
              setState(() {
                _codigoSala = salaController.text.trim();
                _aliasUsuario = aliasController.text.trim().isEmpty ? 'Usuario' : aliasController.text.trim();
              });
              if (mounted) Navigator.pop(ctx);
              await _sincronizarSalaCompartida();
            },
          ),
        ],
      ),
    );
  }

  @override
  void dispose() {
    _watcherSub?.cancel();
    _syncTimer?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final resueltos = _historial.where((e) => !e.procesando).toList();
    final enCola = _historial.where((e) => e.procesando).toList();

    return Scaffold(
      appBar: AppBar(
        title: Text(_pestanaActual == 0
            ? 'Agente SayCheese'
            : 'Solucionario (${resueltos.length})'),
        centerTitle: false,
        actions: [
          IconButton(
            icon: Badge(
              isLabelVisible: _codigoSala.isNotEmpty,
              backgroundColor: Colors.greenAccent,
              child: const Icon(Icons.group_add),
            ),
            tooltip: 'Conectar con otra persona',
            onPressed: _mostrarDialogoSalaCompartida,
          ),
          IconButton(
            icon: const Icon(Icons.settings),
            tooltip: 'Elegir Modelo y API Key',
            onPressed: _mostrarDialogoConfiguracion,
          ),
        ],
      ),
      body: _pestanaActual == 0
          ? _buildVistaAgente(enCola)
          : _buildVistaSoluciones(resueltos),
      bottomNavigationBar: NavigationBar(
        selectedIndex: _pestanaActual,
        onDestinationSelected: (index) => setState(() => _pestanaActual = index),
        destinations: [
          const NavigationDestination(
            icon: Icon(Icons.radar),
            label: 'Agente Activo',
          ),
          NavigationDestination(
            icon: Badge(
              isLabelVisible: resueltos.isNotEmpty,
              label: Text('${resueltos.length}'),
              child: const Icon(Icons.menu_book_rounded),
            ),
            label: 'Solucionario',
          ),
        ],
      ),
    );
  }

  Widget _buildVistaAgente(List<EjercicioResuelto> enCola) {
    return Padding(
      padding: const EdgeInsets.all(16.0),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Card(
            child: ListTile(
              leading: Icon(
                _agenteActivo ? Icons.check_circle : Icons.error,
                color: _agenteActivo ? Colors.greenAccent : Colors.orange,
                size: 36,
              ),
              title: Text(_agenteActivo
                  ? 'Vigilando carpeta SayCheese'
                  : 'Iniciando agente...'),
              subtitle: Text(
                  'Modelo activo: $_modeloSeleccionado\nRuta: $_rutaCarpeta'),
              trailing: IconButton(
                icon: const Icon(Icons.tune),
                onPressed: _mostrarDialogoConfiguracion,
              ),
            ),
          ),
          const SizedBox(height: 8),
          Card(
            color: _codigoSala.isNotEmpty ? Colors.deepPurple.withOpacity(0.3) : null,
            child: ListTile(
              leading: Icon(
                Icons.people_alt_rounded,
                color: _codigoSala.isNotEmpty ? Colors.greenAccent : Colors.grey,
              ),
              title: Text(_codigoSala.isNotEmpty
                  ? 'Sala Conectada: $_codigoSala ($_aliasUsuario)'
                  : 'Modo Individual (Sin sala compartida)'),
              subtitle: Text(_codigoSala.isNotEmpty
                  ? 'Sincronizando respuestas con tu compañero cada 10s'
                  : 'Toca aqui para conectar con otra persona y ver las respuestas juntos'),
              trailing: _sincronizando
                  ? const SizedBox(width: 20, height: 20, child: CircularProgressIndicator(strokeWidth: 2))
                  : const Icon(Icons.arrow_forward_ios, size: 16),
              onTap: _mostrarDialogoSalaCompartida,
            ),
          ),
          const SizedBox(height: 20),
          Text(
            'Procesando en segundo plano (${enCola.length})',
            style: Theme.of(context).textTheme.titleMedium,
          ),
          const SizedBox(height: 12),
          Expanded(
            child: enCola.isEmpty
                ? const Center(
                    child: Text(
                      'Sube o mueve una foto a la carpeta "SayCheese" y se resolvera sola con el modelo elegido.',
                      textAlign: TextAlign.center,
                      style: TextStyle(color: Colors.grey),
                    ),
                  )
                : ListView.builder(
                    itemCount: enCola.length,
                    itemBuilder: (context, index) {
                      final item = enCola[index];
                      return Card(
                        child: ListTile(
                          leading: item.rutaImagen != null
                              ? Image.file(
                                  File(item.rutaImagen!),
                                  width: 50,
                                  height: 50,
                                  fit: BoxFit.cover,
                                  errorBuilder: (_, __, ___) => const Icon(Icons.image),
                                )
                              : const Icon(Icons.cloud_download),
                          title: Text('Resolviendo con ${item.modeloUsado}...'),
                          subtitle: const LinearProgressIndicator(),
                        ),
                      );
                    },
                  ),
          ),
        ],
      ),
    );
  }

  Widget _buildVistaSoluciones(List<EjercicioResuelto> resueltos) {
    return Column(
      children: [
        if (_codigoSala.isNotEmpty)
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
            color: Colors.deepPurple.withOpacity(0.25),
            child: Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Text(
                  'Sala en vivo: $_codigoSala',
                  style: const TextStyle(fontSize: 13, fontWeight: FontWeight.bold),
                ),
                TextButton.icon(
                  icon: const Icon(Icons.sync, size: 18),
                  label: const Text('Actualizar ahora'),
                  onPressed: () => _sincronizarSalaCompartida(),
                ),
              ],
            ),
          ),
        Expanded(
          child: resueltos.isEmpty
              ? const Center(
                  child: Text('Aun no hay hojas resueltas en este apartado.'),
                )
              : ListView.builder(
                  padding: const EdgeInsets.all(12),
                  itemCount: resueltos.length,
                  itemBuilder: (context, index) {
                    final item = resueltos[index];
                    final tieneFotoLocal = item.rutaImagen != null && File(item.rutaImagen!).existsSync();
                    return Card(
                      margin: const EdgeInsets.only(bottom: 12),
                      child: ListTile(
                        contentPadding: const EdgeInsets.all(12),
                        leading: ClipRRect(
                          borderRadius: BorderRadius.circular(8),
                          child: tieneFotoLocal
                              ? Image.file(
                                  File(item.rutaImagen!),
                                  width: 60,
                                  height: 60,
                                  fit: BoxFit.cover,
                                  errorBuilder: (_, __, ___) => const Icon(Icons.image, size: 40),
                                )
                              : Container(
                                  width: 60,
                                  height: 60,
                                  color: Colors.deepPurple.withOpacity(0.3),
                                  child: const Icon(Icons.cloud_done, size: 32),
                                ),
                        ),
                        title: Text('Hoja #${resueltos.length - index} • ${item.autor}'),
                        subtitle: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              'Modelo: ${item.modeloUsado}',
                              style: const TextStyle(fontSize: 11, color: Colors.deepPurpleAccent),
                            ),
                            const SizedBox(height: 4),
                            Text(
                              item.solucion ?? '',
                              maxLines: 2,
                              overflow: TextOverflow.ellipsis,
                            ),
                          ],
                        ),
                        trailing: tieneFotoLocal
                            ? IconButton(
                                icon: const Icon(Icons.refresh),
                                tooltip: 'Reintentar con modelo actual',
                                onPressed: () => _intentarResolver(item),
                              )
                            : const Icon(Icons.arrow_forward_ios, size: 16),
                        onTap: () async {
                          await Navigator.push(
                            context,
                            MaterialPageRoute(
                              builder: (_) => DetalleSolucionScreen(
                                ejercicio: item,
                                onReintentar: tieneFotoLocal
                                    ? () {
                                        Navigator.pop(context);
                                        _intentarResolver(item);
                                      }
                                    : null,
                              ),
                            ),
                          );
                        },
                      ),
                    );
                  },
                ),
        ),
      ],
    );
  }
}

class DetalleSolucionScreen extends StatelessWidget {
  final EjercicioResuelto ejercicio;
  final VoidCallback? onReintentar;

  const DetalleSolucionScreen({
    super.key,
    required this.ejercicio,
    this.onReintentar,
  });

  @override
  Widget build(BuildContext context) {
    final tieneFotoLocal = ejercicio.rutaImagen != null && File(ejercicio.rutaImagen!).existsSync();

    return Scaffold(
      appBar: AppBar(
        title: Text('Solucion (${ejercicio.autor})'),
        actions: [
          if (onReintentar != null)
            IconButton(
              icon: const Icon(Icons.refresh),
              tooltip: 'Reintentar con modelo seleccionado',
              onPressed: onReintentar,
            ),
        ],
      ),
      body: Column(
        children: [
          if (tieneFotoLocal)
            SizedBox(
              height: 200,
              width: double.infinity,
              child: InteractiveViewer(
                child: Image.file(
                  File(ejercicio.rutaImagen!),
                  fit: BoxFit.contain,
                  errorBuilder: (_, __, ___) =>
                      const Center(child: Icon(Icons.broken_image, size: 48)),
                ),
              ),
            ),
          const Divider(height: 1),
          Expanded(
            child: Markdown(
              data: ejercicio.solucion ?? 'Sin respuesta.',
              selectable: true,
            ),
          ),
        ],
      ),
    );
  }
}
